        uint256 maxChunks = tosEncoded.length / 20;
        vm.assume(maxChunks > 0);
        uint256 n = maxChunks;
        if (n > 8) n = 8;
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            uint160 addr = 0;
            for (uint256 j = 0; j < 20; j++) {
                addr = (addr << 8) | uint8(tosEncoded[i * 20 + j]);
            }
            tos[i] = address(addr);
            if (tos[i] == address(0)) tos[i] = address(uint160(i + 1));
        }

        Callee callee = new Callee();

        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

